public class StackFrameParserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static final String FRAME = "    at com.example.app.OrderService.process(OrderService.java:42)";
    static final String NATIVE = "at sun.misc.Unsafe.park(Native Method)";
    static final String NO_PACKAGE = "at Main.main(Main.java:7)";

    public static void main(String[] args) {
        check("className", "com.example.app.OrderService", StackFrameParser.className(FRAME));
        check("methodName", "process", StackFrameParser.methodName(FRAME));
        check("lineNumber", 42, StackFrameParser.lineNumber(FRAME));
        check("className with no package", "Main", StackFrameParser.className(NO_PACKAGE));
        check("methodName with no package", "main", StackFrameParser.methodName(NO_PACKAGE));
        check("a native frame has no line number", -1, StackFrameParser.lineNumber(NATIVE));
        check("className of a native frame", "sun.misc.Unsafe", StackFrameParser.className(NATIVE));
        check("describe", "OrderService.process:42", StackFrameParser.describe(FRAME));
        check("describe a native frame", "Unsafe.park:?", StackFrameParser.describe(NATIVE));
        check("describe a line that is not a frame", "", StackFrameParser.describe("Caused by: IOException"));
        finish();
    }
}

