public class StackFrameParser {

    private static String head(String line) {
        String text = line.trim();
        if (text.startsWith("at ")) {
            text = text.substring(3).trim();
        }
        int paren = text.indexOf('(');
        if (paren >= 0) {
            text = text.substring(0, paren);
        }
        return text.trim();
    }

    public static String className(String line) {
        String head = head(line);
        int dot = head.lastIndexOf('.');
        if (dot < 0) {
            return "";
        }
        return head.substring(0, dot);
    }

    public static String methodName(String line) {
        String head = head(line);
        int dot = head.lastIndexOf('.');
        if (dot < 0) {
            return "";
        }
        return head.substring(dot + 1);
    }

    public static int lineNumber(String line) {
        int paren = line.indexOf('(');
        int close = line.lastIndexOf(')');
        if (paren < 0 || close < paren) {
            return -1;
        }
        String inside = line.substring(paren + 1, close);
        int colon = inside.lastIndexOf(':');
        if (colon < 0) {
            return -1;
        }
        String digits = inside.substring(colon + 1).trim();
        for (int i = 0; i < digits.length(); i++) {
            if (!Character.isDigit(digits.charAt(i))) {
                return -1;
            }
        }
        if (digits.isEmpty()) {
            return -1;
        }
        return Integer.parseInt(digits);
    }

    public static String describe(String line) {
        String type = className(line);
        if (type.isEmpty()) {
            return "";
        }
        int dot = type.lastIndexOf('.');
        String simple = dot < 0 ? type : type.substring(dot + 1);
        int number = lineNumber(line);
        String where = number < 0 ? "?" : String.valueOf(number);
        return simple + "." + methodName(line) + ":" + where;
    }
}
